import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"EmakiAccessory","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/accessory/index.md","filePath":"en/modules/accessory/index.md","lastUpdated":0}`),a={name:`en/modules/accessory/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="emakiaccessory" tabindex="-1">EmakiAccessory <a class="header-anchor" href="#emakiaccessory" aria-label="Permalink to “EmakiAccessory”">​</a></h1><p>EmakiAccessory is the accessory slot module of the Emaki series. It gives players a separate GUI accessory panel that does not occupy vanilla equipment slots, while accessories worn in it still provide attributes and skills.</p><p>The panel is multi-page: <code>parts.yml</code> defines the global parts and slot instances, <code>pages/*.yml</code> decides which parts each page enables, and <code>gui/accessory_gui.yml</code> describes the layout. Page storage is isolated, but <strong>only the currently enabled page</strong> produces attributes, skills, and set piece counts. Accessory attributes and skills reach the player through EmakiAttribute&#39;s contribution provider and EmakiSkills&#39; skill source, so no extra slot configuration is needed in those modules.</p><h2 id="basic-information" tabindex="-1">Basic Information <a class="header-anchor" href="#basic-information" aria-label="Permalink to “Basic Information”">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>Module version</td><td><code>1.1.0</code></td></tr><tr><td>API coordinates</td><td><code>emaki.jiuwu.craft:emaki-accessory-api:1.1.0</code></td></tr><tr><td>Main class</td><td><code>emaki.jiuwu.craft.accessory.EmakiAccessoryPlugin</code></td></tr><tr><td>Main command</td><td><code>/emakiaccessory</code></td></tr><tr><td>Aliases</td><td><code>/eaccessory</code>, <code>/eacc</code></td></tr><tr><td>Required dependency</td><td>EmakiCoreLib</td></tr><tr><td>Optional dependencies</td><td>EmakiItem, EmakiAttribute, EmakiSkills, PlaceholderAPI</td></tr><tr><td>Descriptor baseline</td><td><code>api-version: &quot;1.21.8&quot;</code>, <code>folia-supported: true</code></td></tr><tr><td>Java</td><td>Java 25</td></tr><tr><td>Main permissions</td><td><code>emakiaccessory.use</code> (default true), <code>emakiaccessory.reload</code> (op), <code>emakiaccessory.debug</code> (op), <code>emakiaccessory.admin</code> (op), <code>emakiaccessory.admin.edit</code> (op), <code>emakiaccessory.page.secondary</code> (op, example page permission)</td></tr></tbody></table><h2 id="feature-pages" tabindex="-1">Feature Pages <a class="header-anchor" href="#feature-pages" aria-label="Permalink to “Feature Pages”">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Contents</th></tr></thead><tbody><tr><td><a href="./commands.html">Commands and Permissions</a></td><td>Subcommands, page retrieval, administrative commands, and the 6 permission nodes of <code>/emakiaccessory</code>.</td></tr><tr><td><a href="./configuration.html">Configuration</a></td><td>Slot sources, death drops, deduplication, and persistence in <code>config.yml</code>, plus the fields of <code>pages/*.yml</code>.</td></tr><tr><td><a href="./parts.html">Parts and Slots</a></td><td>Part definitions in <code>parts.yml</code>, slot instance expansion and orphaned slots.</td></tr><tr><td><a href="./sets.html">Accessory Sets</a></td><td>Members, slot criteria, piece thresholds and effects in <code>sets/&lt;set&gt;.yml</code>.</td></tr><tr><td><a href="./gui.html">GUI Template</a></td><td>The four slot types and page switching cells of <code>gui/accessory_gui.yml</code>.</td></tr><tr><td><a href="./integration.html">Attributes and Skills</a></td><td>How accessory attributes reach EmakiAttribute and skills reach EmakiSkills.</td></tr><tr><td><a href="./api.html">API and Integration</a></td><td>The facade and query layer of <code>emaki-accessory-api</code> and their thread constraints.</td></tr><tr><td><a href="./events.html">Event API</a></td><td><code>AccessorySetBonusChangeEvent</code>.</td></tr></tbody></table><h2 id="core-capabilities" tabindex="-1">Core Capabilities <a class="header-anchor" href="#core-capabilities" aria-label="Permalink to “Core Capabilities”">​</a></h2><ul><li><strong>Separate accessory panel:</strong> the accessory panel is its own GUI. It occupies no vanilla equipment slot and shares no slot with EmakiItem equipment.</li><li><strong>Multiple pages with isolated storage:</strong> <code>pages/*.yml</code> defines the pages, and the same slot instance id holds a separate accessory on each page without overwriting.</li><li><strong>Only the enabled page contributes:</strong> accessories on other pages keep their data but stop providing attributes, skills, and set piece counts; the <code>page_enable</code> cell switches the active page.</li><li><strong>Pages can be permission-gated:</strong> a non-empty page <code>permission</code> is matched verbatim. Losing it clears no data and does not switch pages; the player recovers items with <code>/eacc retrieve &lt;page&gt;</code>.</li><li><strong>Parts expand into slot instances:</strong> a part configured with <code>count: 2</code> in <code>parts.yml</code> expands into the slot instances <code>ring_1</code> and <code>ring_2</code>, with one window cell per instance.</li><li><strong>Attributes parsed by the same code as equipment:</strong> accessory attributes go through EmakiAttribute&#39;s own parser, so an accessory and a helmet carrying identical data produce identical numbers, with parent-attribute expansion and range-spread companion keys coming along.</li><li><strong>Thresholds are cumulative:</strong> wearing 3 pieces activates the 2-piece and 3-piece tiers <strong>at the same time</strong>, not one instead of the other.</li><li><strong>Accessory sets never mix with equipment sets:</strong> accessory sets only count pieces inside accessory slots while EmakiItem only counts the equipment slots. One item may belong to both, and each side counts independently.</li><li><strong>Orphaned slots keep their data:</strong> shrinking <code>count</code>, deleting a part, or removing a part from a page deletes nothing. Accessories in a slot that page no longer declares become &quot;orphans&quot; and appear in that page&#39;s orphan area for retrieval. The check is per owning page, so accessories on other pages are never treated as orphans.</li><li><strong>Administrators can view and edit:</strong> <code>/eacc admin view</code> opens a read-only window, while <code>/eacc admin edit</code> additionally requires <code>emakiaccessory.admin.edit</code>.</li></ul><h2 id="file-layout" tabindex="-1">File Layout <a class="header-anchor" href="#file-layout" aria-label="Permalink to “File Layout”">​</a></h2><p>After the server has run, EmakiAccessory mainly uses the following files:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/EmakiAccessory/</span></span>
<span class="line"><span>├─ config.yml</span></span>
<span class="line"><span>├─ parts.yml</span></span>
<span class="line"><span>├─ pages/</span></span>
<span class="line"><span>│  ├─ main.yml</span></span>
<span class="line"><span>│  └─ secondary.yml</span></span>
<span class="line"><span>├─ sets/</span></span>
<span class="line"><span>│  └─ example_set.yml</span></span>
<span class="line"><span>├─ gui/</span></span>
<span class="line"><span>│  └─ accessory_gui.yml</span></span>
<span class="line"><span>└─ lang/</span></span>
<span class="line"><span>   ├─ zh_CN.yml</span></span>
<span class="line"><span>   └─ en_US.yml</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Path</th><th>Description</th></tr></thead><tbody><tr><td><code>config.yml</code></td><td>Main configuration: slot sources, death drops, deduplication, persistence.</td></tr><tr><td><code>parts.yml</code></td><td>Accessory part definitions, deciding which slot instances exist globally.</td></tr><tr><td><code>pages/&lt;page&gt;.yml</code></td><td>Accessory page definition. The id comes from <code>page_id</code>, not the file name; <code>parts</code> decides which parts that page enables.</td></tr><tr><td><code>sets/&lt;set&gt;.yml</code></td><td>Accessory set definition. One set per file; the file name is not used for identification.</td></tr><tr><td><code>gui/accessory_gui.yml</code></td><td>Accessory panel window template, shareable across pages.</td></tr><tr><td><code>lang/*.yml</code></td><td>Command, window and console messages.</td></tr></tbody></table><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting Started”">​</a></h2><ol><li>Put <code>EmakiCoreLib-*.jar</code> and <code>EmakiAccessory-*.jar</code> into the server <code>plugins/</code> folder.</li><li>To make accessories grant attributes and skills, also install EmakiAttribute and EmakiSkills, and define the accessory items with EmakiItem.</li><li>Do <strong>not</strong> put <code>emaki-accessory-api-*.jar</code> into <code>plugins/</code>; the API Jar is a compile-time dependency for developers only.</li><li>After the first start, review <code>plugins/EmakiAccessory/parts.yml</code>, <code>pages/main.yml</code>, and <code>gui/accessory_gui.yml</code>.</li><li>Open your own accessory panel:</li></ol><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/eacc open</span></span>
<span class="line"><span>/eacc open secondary</span></span></code></pre></div><ol start="6"><li>Inspect all pages and the currently enabled one:</li></ol><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/eacc pages</span></span></code></pre></div><ol start="7"><li>Reload configuration, parts, pages, and sets after editing:</li></ol><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/eacc reload</span></span></code></pre></div><h2 id="usage-notes" tabindex="-1">Usage Notes <a class="header-anchor" href="#usage-notes" aria-label="Permalink to “Usage Notes”">​</a></h2><ul><li>After changing parts or <code>count</code> in <code>parts.yml</code>, place a matching cell with <code>type: &quot;accessory_slot&quot;</code> and the same key name in <code>gui/accessory_gui.yml</code> for every expanded slot instance, and make sure the target page declares that part in its <code>parts</code> list.</li><li>Attributes, skills, and set piece counts only count the currently enabled page. Accessories on a page take effect only after the player switches to it.</li><li><code>unique: true</code> is judged by EmakiItem&#39;s item definition id where available. It does not switch off when EmakiItem is absent; it falls back to vanilla material matching, so two accessories of the same material count as duplicates.</li><li><code>pieces[].item</code> in accessory sets also depends on EmakiItem definition ids; the whole set is inactive when EmakiItem is absent.</li><li>A part id must not end with <code>_&lt;number&gt;</code>, which would collide with slot instance ids.</li><li><code>/eacc admin edit</code> only works for online players; <code>/eacc admin clear</code> cannot be undone and is written to the log.</li></ul>`,22)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};